/* Lightweight Chart.js-like stub for stacked horizontal bar charts
 * Provides a minimal global `Chart` with: new Chart(canvas, {type:'bar', data, options})
 * Supports options: indexAxis:'y', scales.{x,y}.stacked, responsive, maintainAspectRatio
 * Datasets: [{label, data:[...], backgroundColor}]  where data[i] is a number
 * Includes simple hover tooltip and window resize handling.
 */
(function(){
  function createEl(tag, cls){ var el=document.createElement(tag); if(cls) el.className=cls; return el; }
  function getCtx(canvas){ return canvas.getContext('2d'); }
  function Chart(canvas, cfg){
    if(!(this instanceof Chart)) return new Chart(canvas, cfg);
    this.canvas = canvas.nodeType ? canvas : canvas.canvas;
    this.ctx = getCtx(this.canvas);
    this.config = cfg||{};
    this._tooltip = createEl('div', 'chartjs-lite-tooltip');
    Object.assign(this._tooltip.style, {position:'absolute',pointerEvents:'none',background:'rgba(17,24,39,.92)',color:'#fff',font:'12px sans-serif',padding:'4px 6px',borderRadius:'4px',transform:'translate(-50%, -130%)',zIndex:10,display:'none'});
    this.canvas.parentNode && this.canvas.parentNode.appendChild(this._tooltip);
    var self=this;
    this.canvas.addEventListener('mousemove', function(e){ self._onMove(e); });
    this.canvas.addEventListener('mouseleave', function(){ self._tooltip.style.display='none'; });
    window.addEventListener('resize', function(){ self.resize(); });
    this.resize();
  }
  Chart.prototype.update = function(cfg){ if(cfg) this.config=cfg; this._render(); };
  Chart.prototype.resize = function(){
    var par = this.canvas.parentNode || document.body;
    var width = par.clientWidth || 600;
    this.canvas.width = width;
    // height should be set by caller; keep current
    this._render();
  };
  Chart.prototype._calc = function(){
    var data = (this.config.data||{});
    var labels = data.labels||[];
    var sets = data.datasets||[];
    var opts = this.config.options||{};
    var idxY = (opts.indexAxis||'x')==='y';
    var padding = {top:20,right:20,bottom:20,left:120};
    var W=this.canvas.width, H=this.canvas.height;
    var innerW=W-padding.left-padding.right, innerH=H-padding.top-padding.bottom;
    var stack = (opts.scales&&opts.scales.x&&opts.scales.x.stacked) || (opts.scales&&opts.scales.y&&opts.scales.y.stacked);
    // compute totals for stacked
    var max=0;
    for(var i=0;i<labels.length;i++){
      var s=0; for(var d=0; d<sets.length; d++){ var v=+((sets[d].data||[])[i]||0); if(stack){ s+=v; } else { s=Math.max(s,v); } }
      if(s>max) max=s;
    }
    if(max<=0) max=1;
    var barGap = 8;
    var rowH = Math.max(16, Math.min(38, (innerH - (labels.length-1)*barGap) / (labels.length||1)) );
    // build rects
    var rects=[]; // {x,y,w,h,labelIdx,dsIdx,val}
    for(var i=0;i<labels.length;i++){
      var x0=padding.left, y0=padding.top + i*(rowH+barGap);
      var acc=0;
      for(var d=0; d<sets.length; d++){
        var v=+((sets[d].data||[])[i]||0);
        var w = innerW*(v/max);
        rects.push({x:x0+acc, y:y0, w:w, h:rowH, labelIdx:i, dsIdx:d, val:v});
        acc+=w;
      }
    }
    return {labels:labels, sets:sets, max:max, padding:padding, innerW:innerW, innerH:innerH, rowH:rowH, rects:rects};
  };
  Chart.prototype._render = function(){
    var ctx=this.ctx; var W=this.canvas.width, H=this.canvas.height; ctx.clearRect(0,0,W,H);
    var C=this._calc(); this._calcCache=C;
    var p=C.padding; ctx.fillStyle='#f8fafc'; ctx.fillRect(p.left, p.top, C.innerW, C.innerH);
    // axes labels (y-axis)
    ctx.fillStyle='#334155'; ctx.font='12px sans-serif'; ctx.textBaseline='middle';
    for(var i=0;i<C.labels.length;i++){
      var y=p.top + i*(C.rowH+8) + C.rowH/2; ctx.textAlign='right';
      ctx.fillText(C.labels[i], p.left-8, y);
    }
    // grid lines and ticks (x)
    ctx.strokeStyle='#e5e7eb'; ctx.lineWidth=1; ctx.beginPath();
    for(var t=0;t<=4;t++){
      var x=p.left + (C.innerW*(t/4)); ctx.moveTo(x,p.top); ctx.lineTo(x, p.top+C.innerH);
    }
    ctx.stroke();
    // bars
    function parseColor(col){
      if(!col) return [96,165,250]; // default #60a5fa
      if(/^#/.test(col)){
        var h=col.replace('#',''); if(h.length===3){ h=h.replace(/(.)/g,'$1$1'); }
        var n=parseInt(h,16); return [(n>>16)&255,(n>>8)&255,n&255];
      }
      var m = String(col).match(/rgba?\(([^)]+)\)/i);
      if(m){ var p=m[1].split(',').map(function(x){return parseFloat(x);}); return [p[0]||0,p[1]||0,p[2]||0]; }
      return [96,165,250];
    }
    function textColorFor(bg){ var r=bg[0],g=bg[1],b=bg[2]; var lum = 0.2126*r + 0.7152*g + 0.0722*b; return lum>170 ? '#111827' : '#ffffff'; }
    ctx.font='12px sans-serif'; ctx.textBaseline='middle'; ctx.textAlign='center';
    for(var r=0;r<C.rects.length;r++){
      var R=C.rects[r];
      var ds=C.sets[R.dsIdx]; var color = (ds && ds.backgroundColor) || '#60a5fa';
      ctx.fillStyle=color; ctx.fillRect(R.x, R.y, Math.max(1,R.w), R.h);
      // value label inside the segment when it fits
      var val = (R.val==null?0:R.val);
      if(val>0){
        var txt = String(val);
        var tw = ctx.measureText(txt).width + 6;
        if(R.w >= Math.max(22, tw)){
          var bg = parseColor(color);
          ctx.fillStyle = textColorFor(bg);
          ctx.fillText(txt, R.x + R.w/2, R.y + R.h/2);
        }
      }
    }
  };
  Chart.prototype._onMove = function(e){
    var rect=this.canvas.getBoundingClientRect();
    var x=e.clientX-rect.left, y=e.clientY-rect.top;
    var C=this._calcCache; if(!C){ this._tooltip.style.display='none'; return; }
    var hit=null;
    for(var i=0;i<C.rects.length;i++){ var R=C.rects[i]; if(x>=R.x && x<=R.x+R.w && y>=R.y && y<=R.y+R.h){ hit=R; break; } }
    if(hit){
      var ds=C.sets[hit.dsIdx]; var label=C.labels[hit.labelIdx];
      this._tooltip.innerHTML = '<strong>'+ (ds.label||'') +'</strong><br/>'+ label +': '+ hit.val;
      this._tooltip.style.display='block';
      this._tooltip.style.left = (x+rect.left)+'px';
      this._tooltip.style.top = (y+rect.top)+'px';
    } else {
      this._tooltip.style.display='none';
    }
  };
  window.Chart = Chart;
})();
